#!/usr/bin/env node
import { createRequest, listRequests, updateStatus } from './store.js';
import { argv } from 'process';

const command = argv[2];

try {
  switch (command) {
    case 'create': {
      if (argv.length < 5) {
        console.error('Error: Usage - node src/index.js create "<title>" "<description>"');
        process.exit(1);
      }

      const title = argv[3];
      const description = argv[4];

      const newRequest = createRequest(title, description);
      console.log(newRequest.id);
      break;
    }

    case 'list': {
      if (argv.length !== 3) {
        console.error('Error: Usage - node src/index.js list');
        process.exit(1);
      }

      const requests = listRequests();
      console.log(JSON.stringify(requests, null, 2));
      break;
    }

    case 'update': {
      if (argv.length !== 5) {
        console.error('Error: Usage - node src/index.js update <id> <new-status>');
        process.exit(1);
      }

      const id = argv[3];
      const newStatus = argv[4];

      const updatedRequest = updateStatus(id, newStatus);
      console.log(JSON.stringify(updatedRequest, null, 2));
      break;
    }

    default: {
      console.error('Error: Unknown command. Use create, list, or update.');
      process.exit(1);
    }
  }
} catch (error) {
  console.error(`Error: ${error.message}`);
  process.exit(1);
}

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { join } from 'path';

const DATA_DIR = 'data';
const REQUESTS_FILE = join(DATA_DIR, 'requests.json');

// Ensure data directory exists
if (!existsSync(DATA_DIR)) {
  mkdirSync(DATA_DIR);
}

// Initialize requests file if it doesn't exist
if (!existsSync(REQUESTS_FILE)) {
  writeFileSync(REQUESTS_FILE, '[]');
}

// Helper function to read requests from file
const readRequests = () => {
  try {
    const data = readFileSync(REQUESTS_FILE, 'utf8');
    return JSON.parse(data);
  } catch (error) {
    console.error('Error reading requests:', error);
    return [];
  }
};

// Helper function to write requests to file
const writeRequests = (requests) => {
  try {
    writeFileSync(REQUESTS_FILE, JSON.stringify(requests, null, 2));
  } catch (error) {
    console.error('Error writing requests:', error);
    throw error;
  }
};

// Valid status transitions
const VALID_TRANSITIONS = {
  'open': ['in_progress'],
  'in_progress': ['resolved'],
  'resolved': []
};

// Create a new request
export const createRequest = (title, description) => {
  if (!title || title.trim() === '') {
    throw new Error('Title cannot be empty');
  }

  const requests = readRequests();
  const newRequest = {
    id: Date.now().toString(),
    title: title.trim(),
    description: description.trim(),
    status: 'open',
    createdAt: new Date().toISOString()
  };

  requests.push(newRequest);
  writeRequests(requests);

  return newRequest;
};

// List all requests
export const listRequests = () => {
  return readRequests();
};

// Update request status
export const updateStatus = (id, newStatus) => {
  const requests = readRequests();
  const requestIndex = requests.findIndex(req => req.id === id);

  if (requestIndex === -1) {
    throw new Error(`Request with id ${id} not found`);
  }

  const request = requests[requestIndex];
  const currentStatus = request.status;

  if (!VALID_TRANSITIONS.hasOwnProperty(newStatus)) {
    throw new Error(`Invalid status: ${newStatus}`);
  }

  if (currentStatus === newStatus) {
    throw new Error(`Status is already ${newStatus}`);
  }

  if (!VALID_TRANSITIONS[currentStatus].includes(newStatus)) {
    throw new Error(`Cannot transition from ${currentStatus} to ${newStatus}`);
  }

  request.status = newStatus;
  writeRequests(requests);

  return request;
};

