test('invalid transition is rejected', () => {
  const request = createRequest('Test Title', 'Test Description');
  const id = request.id;

  // Try to go from open directly to resolved (should fail)
  assert.throws(() => {
    updateStatus(id, 'resolved');
  }, /Cannot transition from open to resolved/);

  // Try to go backwards (should fail)
  const updated = updateStatus(id, 'in_progress');
  assert.strictEqual(updated.status, 'in_progress');

  assert.throws(() => {
    updateStatus(id, 'open');
  }, /Cannot transition from in_progress to open/);

  // Try same status (should fail)
  assert.throws(() => {
    updateStatus(id, 'in_progress');
  }, /Status is already in_progress/);

  // Try unknown status (should fail)
  assert.throws(() => {
    updateStatus(id, 'unknown_status');
  }, /Invalid status: unknown_status/);
});

test('unknown id is rejected', () => {
  assert.throws(() => {
    updateStatus('nonexistent_id', 'in_progress');
  }, /Request with id nonexistent_id not found/);
});

#!/usr/bin/env node

import { createRequest, listRequests, updateStatus } from './store.js';
import { argv } from 'process';

// CLI commands
const commands = {
  create: async (title, description) => {
    try {
      const newRequest = await createRequest(title, description);
      console.log(newRequest.id);
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
  },

  list: async () => {
    try {
      const requests = await listRequests();
      console.log(JSON.stringify(requests, null, 2));
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(2);
    }
  },

  update: async (id, newStatus) => {
    try {
      const updatedRequest = await updateStatus(id, newStatus);
      console.log(JSON.stringify(updatedRequest, null, 2));
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exit(1);
    }
  }
};

// Main function
async function main() {
  // Skip first two args (node and script path)
  const [command, ...args] = argv.slice(2);

  if (!command) {
    console.error('Error: No command provided');
    console.log('Usage:');
    console.log('  node src/index.js create "<title>" "<description>"');
    console.log('  node src/index.js list');
    console.log('  node src/index.js update <id> <new-status>');
    process.exit(1);
  }

  if (!commands[command]) {
    console.error(`Error: Unknown command "${command}"`);
    console.log('Available commands: create, list, update');
    process.exit(1);
  }

  // Validate arguments for each command
  switch (command) {
    case 'create':
      if (args.length < 2) {
        console.error('Error: create command requires title and description');
        process.exit(1);
      }
      // Trim whitespace from arguments
      await commands.create(args[0].trim(), args[1].trim());
      break;

    case 'list':
      if (args.length > 0) {
        console.error('Error: list command does not take arguments');
        process.exit(1);
      }
      await commands.list();
      break;

    case 'update':
      if (args.length < 2) {
        console.error('Error: update command requires id and new-status');
        process.exit(1);
      }
      await commands.update(args[0], args[1]);
      break;
  }
}

main();

import { promises as fs } from 'fs';
import { join } from 'path';

const DATA_DIR = 'data';
const REQUESTS_FILE = join(DATA_DIR, 'requests.json');

// Initialize data directory and file if they don't exist
async function initializeDataStore() {
  try {
    await fs.access(DATA_DIR);
  } catch {
    await fs.mkdir(DATA_DIR, { recursive: true });
  }

  try {
    await fs.access(REQUESTS_FILE);
  } catch {
    await fs.writeFile(REQUESTS_FILE, '[]');
  }
}

// Load requests from file
export async function loadRequests() {
  await initializeDataStore();
  try {
    const data = await fs.readFile(REQUESTS_FILE, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    console.error(`Error reading requests file: ${error.message}`);
    return [];
  }
}

// Save requests to file
export async function saveRequests(requests) {
  await initializeDataStore();
  try {
    await fs.writeFile(REQUESTS_FILE, JSON.stringify(requests, null, 2));
  } catch (error) {
    console.error(`Error saving requests file: ${error.message}`);
    throw error;
  }
}

// Generate a unique ID
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

// Create a new request
export async function createRequest(title, description) {
  if (!title || title.trim() === '') {
    throw new Error('Title cannot be empty');
  }

  const requests = await loadRequests();
  const newRequest = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'open',
    createdAt: new Date().toISOString(),
  };

  requests.push(newRequest);
  await saveRequests(requests);
  return newRequest;
}

// List all requests
export async function listRequests() {
  return await loadRequests();
}

// Update request status
export async function updateStatus(id, newStatus) {
  const requests = await loadRequests();
  const requestIndex = requests.findIndex(req => req.id === id);

  if (requestIndex === -1) {
    throw new Error(`Request with id ${id} not found`);
  }

  const request = requests[requestIndex];
  const currentStatus = request.status;

  // Validate new status
  const validStatuses = ['open', 'in_progress', 'resolved'];
  if (!validStatuses.includes(newStatus)) {
    throw new Error(`Invalid status: ${newStatus}`);
  }

  // Validate transition
  if (currentStatus === newStatus) {
    throw new Error(`Status is already ${newStatus}`);
  }

  if (currentStatus === 'open' && newStatus === 'resolved') {
    throw new Error('Cannot transition directly from open to resolved');
  }

  if (currentStatus === 'resolved' && newStatus !== 'resolved') {
    throw new Error('Cannot transition from resolved to any other status');
  }

  if (currentStatus === 'in_progress' && newStatus === 'open') {
    throw new Error('Cannot transition from in_progress to open');
  }

  // Update the status
  requests[requestIndex].status = newStatus;
  await saveRequests(requests);
  return requests[requestIndex];
}

import { test } from 'node:test';
